# Terraform Module: S3 + RDS + IAM (dev/prod)

## Structure

```
.
├── modules/
│   ├── s3-bucket/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam-service-account/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
└── versions.tf
```

## Root module

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }

  backend "s3" {
    # Terraform workspaces give per-env state: env:/<workspace>
    bucket         = "my-terraform-state"
    key            = "app/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

### `variables.tf`

```hcl
variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be 'dev' or 'prod'."
  }
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "replica_region" {
  description = "Cross-region replication target for prod bucket; empty disables replication"
  type        = string
  default     = ""
}

# --- S3 ---
variable "bucket_name_prefix" {
  type    = string
  default = "myapp-assets"
}

# --- RDS ---
variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type    = bool
  default = false
}

variable "db_name" {
  type    = string
  default = "appdb"
}

variable "db_username" {
  type    = string
  default = "appadmin"
}

variable "db_backup_retention_days" {
  description = "Backup retention. Acceptance requires >= 7."
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "Backup retention must be >= 7 days."
  }
}

# --- IAM / EKS ---
variable "eks_cluster_name" {
  description = "EKS cluster for OIDC trust (used in prod; empty creates user-based access for dev)"
  type        = string
  default     = ""
}

variable "eks_oidc_provider_arn" {
  description = "OIDC provider ARN of the EKS cluster (prod only)"
  type        = string
  default     = ""
}

variable "node_instance_type" {
  type    = string
  default = "t3.medium"
}

variable "node_count" {
  type    = number
  default = 2
}
```

### `main.tf`

```hcl
provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  name_prefix = "${var.bucket_name_prefix}-${var.environment}-${data.aws_caller_identity.current.account_id}"
  is_prod     = var.environment == "prod"
}

resource "random_password" "db_master" {
  length  = 32
  special = false
}

module "s3_assets" {
  source = "./modules/s3-bucket"

  name                = local.name_prefix
  replication_region  = var.replica_region      # set to us-west-2 in prod only
  replication_role_arn = var.replica_region != "" ? aws_iam_role.replication[0].arn : null
}

module "rds" {
  source = "./modules/rds"

  identifier           = "${var.environment}-app-postgres"
  instance_class       = var.db_instance_class
  multi_az             = var.db_multi_az
  db_name              = var.db_name
  username             = var.db_username
  password_secret_name = "${var.environment}/db/master-password"
  backup_retention_days = var.db_backup_retention_days

  password = random_password.db_master.result
}

module "service_account_iam" {
  source = "./modules/iam-service-account"

  name                  = "svc-${var.environment}-web"
  use_oidc_trust        = local.is_prod
  eks_cluster_name      = var.eks_cluster_name
  eks_oidc_provider_arn = var.eks_oidc_provider_arn
  aws_account_id        = data.aws_caller_identity.current.account_id
  partition             = data.aws_partition.current.partition

  bucket_read_arns = [module.s3_assets.bucket_arn, "${module.s3_assets.bucket_arn}/*"]
}
```

Prod-only cross-region replication role:

```hcl
resource "aws_iam_role" "replication" {
  count = var.replica_region != "" ? 1 : 0
  name  = "${var.environment}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replica_region != "" ? 1 : 0
  name  = "replication-permissions"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = [module.s3_assets.bucket_arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${module.s3_assets.bucket_arn}/*"]
      },
      {
        Effect = "Allow"
        Action = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = [
          module.s3_assets.replica_bucket_arn,
          "${module.s3_assets.replica_bucket_arn}/*"
        ]
      }
    ]
  })
}
```

### `outputs.tf`

```hcl
output "assets_bucket" {
  value = { id = module.s3_assets.bucket_id, arn = module.s3_assets.bucket_arn }
}

output "rds_endpoint" {
  value = module.rds.endpoint
}

output "service_account_role_arn" {
  value = module.service_account_iam.role_arn
}

output "db_credentials_secret_arn" {
  value = module.rds.password_secret_arn
}
```

