## `modules/s3-bucket/main.tf`

```hcl
resource "aws_s3_bucket" "this" {
  bucket        = var.name
  force_destroy = ! var.enable_replication # dev can be destroyed, prod cannot easily
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = var.kms_key_arn
      sse_algorithm     = var.kms_key_arn == null ? "AES256" : "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---- Optional cross-region replication (prod) ----

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role_arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    filter {}

    delete_marker_replication { status = "Enabled" }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD_IA"
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket" "replica" {
  count         = var.enable_replication ? 1 : 0
  bucket        = "${var.name}-replica"
  provider      = aws.replica
}

resource "aws_s3_bucket_versioning" "replica" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count                   = var.enable_replication ? 1 : 0
  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
```

`providers.tf` (module-level dual-region provider):

```hcl
provider "aws" {}
provider "aws" {
  alias  = "replica"
  region = var.replication_region != "" ? var.replication_region : var.default_region
}
```

## `modules/s3-bucket/variables.tf` / `outputs.tf`

```hcl
variable "name"               { type = string }
variable "kms_key_arn"        { type = string, default = null }
variable "enable_replication" { type = bool, default = false }
variable "replication_region" { type = string, default = "" }
variable "default_region"     { type = string, default = "us-east-1" }
variable "replication_role_arn" { type = string, default = null }

locals { enable_replication = var.enable_replication && var.replication_region != "" }
```
*(In `main.tf`, reference `local.enable_replication` where `var.enable_replication` is used above.)*

```hcl
output "bucket_id"          { value = aws_s3_bucket.this.id }
output "bucket_arn"         { value = aws_s3_bucket.this.arn }
output "replica_bucket_arn" { value = var.enable_replication ? aws_s3_bucket.replica[0].arn : null }
```

