## `modules/rds/main.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.identifier}-subnet-group"
  subnet_ids = var.subnet_ids
}

resource "aws_db_parameter_group" "this" {
  family = "postgres16"
  name   = "${var.identifier}-params"

  parameter {
    name  = "log_connections"
    value = "1"
  }
}

resource "aws_db_instance" "this" {
  identifier = var.identifier

  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = var.instance_class

  allocated_storage     = var.allocated_storage_gb
  max_allocated_storage = var.allocated_storage_gb * 4

  db_name  = var.db_name
  username = var.username
  password = var.password

  db_subnet_group_name   = aws_db_subnet_group.this.name
  parameter_group_name   = aws_db_parameter_group.this.name
  port                   = 5432
  vpc_security_group_ids = var.security_group_ids

  multi_az = var.multi_az

  # Acceptance criteria
  publicly_accessible    = false
  deletion_protection    = true
  storage_encrypted      = true
  backup_retention_period = var.backup_retention_days
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:04:30-sun:05:30"

  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.identifier}-final"

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  lifecycle {
    prevent_destroy = true
  }
}

# Connection string secret — encrypted at rest by Secrets Manager KMS key, never in tfstate plaintext vars committed to Git
resource "aws_secretsmanager_secret" "db_url" {
  name                    = "${var.password_secret_name}-url"
  kms_key_id              = var.kms_key_arn
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db_url" {
  secret_id = aws_secretsmanager_secret.db_url.id
  secret_string = jsonencode({
    url      = "postgresql://${var.username}:${urlencode(var.password)}@${aws_db_instance.this.endpoint}/${var.db_name}"
    host     = aws_db_instance.this.address
    port     = 5432
    dbname   = var.db_name
    username = var.username
  })
}
```

`modules/rds/variables.tf` highlights:

```hcl
variable "identifier"              { type = string }
variable "instance_class"          { type = string }
variable "multi_az"                { type = bool, default = false }
variable "engine_version"          { type = string, default = "16.3" }
variable "db_name"                 { type = string }
variable "username"                { type = string }
variable "password"                { type = string, sensitive = true }
variable "allocated_storage_gb"    { type = number, default = 50 }
variable "backup_retention_days" {
  type    = number
  default = 7
  validation {
    condition     = var.backup_retention_days >= 7
    error_message = "Must be >= 7."
  }
}
variable "subnet_ids"           { type = list(string), default = [] }
variable "security_group_ids"   { type = list(string), default = [] }
variable "kms_key_arn"          { type = string, default = null }
variable "password_secret_name" { type = string }
```

Outputs:

```hcl
output "endpoint"          { value = aws_db_instance.this.endpoint }
output "instance_arn"      { value = aws_db_instance.this.arn }
output "password_secret_arn" { value = aws_secretsmanager_secret.db_url.arn }
```

