## `modules/iam-service-account/main.tf`

Two access modes driven by `use_oidc_trust`: **prod** gets an OIDC-federated least-privilege role (no static keys, no wildcards); **dev** falls back to a user with programmatic access.

```hcl
# ---------- Role (always created; trust depends on mode) ----------
resource "aws_iam_role" "this" {
  name = var.name

  assume_role_policy = jsonencode(
    var.use_oidc_trust ? {
      Version = "2012-10-17"
      Statement = [{
        Effect = "Allow"
        Principal = {
          Federated = var.eks_oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(var.eks_oidc_provider_arn, "/^(.*provider/)/", "")}:sub" =
              "system:serviceaccount:${var.k8s_namespace}:${var.k8s_service_account}"
          }
        }
      }]
      } : {
      Version = "2012-10-17"
      Statement = [{
        Effect    = "Allow"
        Principal = { AWS = "arn:${var.partition}:iam::${var.aws_account_id}:root" }
        Action    = "sts:AssumeRole"
      }]
    }
  )
}

# Least privilege: explicit read-only on the app bucket, no wildcards on actions
resource "aws_iam_role_policy" "bucket_access" {
  name = "${var.name}-bucket-access"
  role = aws_iam_role.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [{
        Sid      = "ReadObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:ListBucket"]  # no wildcard actions
        Resource = var.bucket_read_arns
      }],
      var.allow_write ? [{
        Sid      = "WriteObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = var.bucket_read_arns[1]
      }] : []
    )
  })
}

# ---------- Dev path: programmatic user assuming the role ----------
resource "aws_iam_user" "this" {
  count = var.use_oidc_trust ? 0 : 1
  name  = "${var.name}-user"
}

resource "aws_iam_access_key" "this" {
  count = var.use_oidc_trust ? 0 : 1
  user  = aws_iam_user.this[0].name
}

resource "aws_iam_user_policy" "assume_role" {
  count = var.use_oidc_trust ? 0 : 1
  name  = "assume-${var.name}"
  user  = aws_iam_user.this[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "sts:AssumeRole"
      Resource = aws_iam_role.this.arn
    }]
  })
}
```

Variables include `k8s_namespace = "app"`, `k8s_service_account = "web"`, `allow_write` (true in dev, tune per service).

Outputs:

```hcl
output "role_arn"         { value = aws_iam_role.this.arn }
output "access_key_id"    { value = var.use_oidc_trust ? null : aws_iam_access_key.this[0].id }
output "secret_access_key" {
  value     = var.use_oidc_trust ? null : aws_iam_access_key.this[0].secret
  sensitive = true
}
```

